        { childId: "ipt_isurCd_2", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isurCd"))); } },
        { childId: "ipt_view", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("view"))); } },
        { childId: "ipt_listSchdlDd", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("listSchdlDd"))); } }];
    let copied = 0;
