*/
scwin.trim = function (str) {
    /* sdd-asis-lifecycle:begin trim — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    str = str.replace(/^\s*/, '').replace(/\s*$/, '');
    return str;
    /* sdd-asis-lifecycle:end */
};


