};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.NewListStkcertIsuStatDtlForm || { elements: [] });
    const listSchdlDd = $c.util.getComponent('ipt_listSchdlDd');
    const isuCd = $c.util.getComponent('ipt_isuCd');
    const stkcertKindCd = $c.util.getComponent('slc_stkcertKindCd');
    const stkIsuRsnCd = $c.util.getComponent('slc_stkIsuRsnCd');
    const listMethdTpCd = $c.util.getComponent('slc_listMethdTpCd');
    const indefinpdYn = frm.indefinpdYn;
    const prefstkEndDd = $c.util.getComponent('cal_prefstkEndDd');
    const isuEngSymbl = $c.util.getComponent('ipt_isuEngSymbl');
    const divReckDd1 = $c.util.getComponent('cal_divReckDd1');
    if (($c.util.getComponent("dma_registerReq").get("listSchdlDd") == null ? '' : String($c.util.getComponent("dma_registerReq").get("listSchdlDd"))) === '') {
        await $c.win.alert('상장(희망)일을 입력하십시오');
        listSchdlDd.select();
        return;
    }
    if (($c.util.getComponent("dma_registerReq").get("divReckDd1") == null ? '' : String($c.util.getComponent("dma_registerReq").get("divReckDd1"))) === '') {
        await $c.win.alert('배당기산일_1을 입력하십시오');
        $c.util.getComponent("cal_divReckDd1").focus();
        return;
    }
    if (($c.util.getComponent("dma_registerReq").get("isuCd") == null ? '' : String($c.util.getComponent("dma_registerReq").get("isuCd"))) === '') {
        await $c.win.alert('종목코드를 입력하십시오');
        isuCd.select();
        return;
    }
    if (document.stkcertKindCd.value === '') {
        await $c.win.alert('주식 종류를 입력하십시오');
    }
    if (document.stkIsuRsnCd.value === '') {
        await $c.win.alert('주식 발행 사유를 입력하십시오');
        $c.util.getComponent("slc_stkIsuRsnCd").focus();
        return;
    }
    if (document.listMethdTpCd.value === '') {
        await $c.win.alert('상장방식을 입력하십시오');
        $c.util.getComponent("slc_listMethdTpCd").focus();
        return;
    }
    if (indefinpdYn.value === 'Y') {
        $c.util.getComponent("cal_prefstkEndDd").setValue('');
    }
    if (($c.util.getComponent("dma_registerReq").get("isuEngSymbl") == null ? '' : String($c.util.getComponent("dma_registerReq").get("isuEngSymbl"))) === '') {
        await $c.win.alert('종목심볼을 입력해 주십시오');
        isuEngSymbl.select();
        return;
    }
    if (!(String(($c.util.getComponent('rd_nparvalstkYn'))?.getValue?.() ?? "") !== "")) {
        await $c.win.alert('무액면주식여부는 필수 입니다.');
        return;
    }
    if (($c.util.getComponent('ipt_parval').getValue() == null ? '' : String($c.util.getComponent('ipt_parval').getValue())) === '') {
        await $c.win.alert('액면가/개별주당자본금은 필수 입니다.');
        return;
    }
    $c.util.getComponent('slc_stkcertKindCd').setDisabled(false);
    $c.util.getComponent('slc_currIsoCd').setDisabled(false);
    frm.action = 'newListStkcertIsuStat.do';
    $c.util.getComponent('dma_registerReq').set('method', 'insertStkcertIsuStatDtl');
    await scwin.tx_fn_register();
    /* sdd-asis-lifecycle:end */
};


